/**
 * Run every cell of a plan and fold the leaderboard. A cell whose run
 * throws is kept as an error outcome; the fleet run itself rejects only for
 * a plan it cannot start.
 * @param plan - environments, model routes, repetitions, workspace root, group, and abort signal.
 * @returns every cell's outcome in plan order and the leaderboard folded from the reports.
 * @throws {@link FleetError} when the plan selects no environment or asks for no repetition.
 */
async run(plan: FleetPlan): Promise<FleetRunReport> {
  if (!Number.isInteger(plan.repetitions) || plan.repetitions < 1) {
    throw new FleetError(`repetitions must be a positive integer, got ${String(plan.repetitions)}`, 'FLEET_INVALID_PLAN')
  }
  const definitions = this.select(plan)
  if (definitions.size === 0) throw new FleetError('the plan selects no environment', 'FLEET_EMPTY_PLAN')
  const models = plan.models.length === 0 ? [this.defaultModel()] : plan.models
  const group = plan.group ?? `fleet-${randomUUID()}`
  const cells: FleetCell[] = []
  for (const environment of definitions.keys()) {
    for (const model of models) {
      for (let repetition = 0; repetition < plan.repetitions; repetition += 1) cells.push({ environment, model, repetition })
    }
  }
  const outcomes = await bounded(cells.map(cell => () => this.runCell(cell, plan, group)), this.resolved.maxConcurrent)
  return { group, cells: outcomes, leaderboard: foldLeaderboard(outcomes, definitions) }
}

